import React, { useEffect, useState } from 'react';
import AddProductForm from '../components/Invetory/AddProductForm';
import ProductsTable from '../components/Invetory/ProductsTable';
import Notification from '../components/Invetory/Notification';
import CategoryCollapse from '../components/Invetory/CategoryCollapse';

function InventoryPage() {
    const [products, setProducts] = useState([]);
    const [categories, setCategories] = useState([]);
    const [categoryFilter, setCategoryFilter] = useState('all');
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState('');
    const [messageType, setMessageType] = useState('success');
    const [showCategory, setShowCategory] = useState(false);

    useEffect(() => {
        loadProducts();
        loadCategories();
    }, []);

    const loadProducts = async () => {
        setLoading(true);
        setMessage('');
        try {
            const res = await fetch('http://localhost:3001/api/productos');
            const data = await res.json();
            setProducts(data);
        } catch (err) {
            console.error("Error al cargar productos en frontend:", err);
            setMessage('Error al cargar productos');
            setMessageType('danger');
        } finally {
            setLoading(false);
        }
    };

    const loadCategories = async () => {
        try {
            const res = await fetch('http://localhost:3001/api/categorias');
            const data = await res.json();
            const mappedCategories = data.map(cat => ({
                id: cat.id,
                codigo_categoria: cat.codigo_categoria,
                nombre_categoria: cat.nombre_categoria
            }));
            setCategories(mappedCategories);
        } catch (err) {
            console.error("Error al cargar categorías en frontend:", err);
        }
    };

    const handleUpdateProduct = async (updatedProduct) => {
        setLoading(true);
        setMessage('');
        try {
            const res = await fetch(`http://localhost:3001/api/productos/${updatedProduct.id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(updatedProduct)
            });
            const result = await res.json();
            if (result.success) {
                setMessage('Producto actualizado con éxito');
                setMessageType('success');
                loadProducts();
            } else {
                setMessage(result.message || 'Error al actualizar producto');
                setMessageType('danger');
            }
        } catch (err) {
            console.error("Error al actualizar producto en frontend:", err);
            setMessage('Error de comunicación al actualizar producto');
            setMessageType('danger');
        } finally {
            setLoading(false);
        }
    };

    const handleAddCategory = async (cat) => {
        if (!cat.name) {
            setMessage('El nombre de la categoría es obligatorio.');
            setMessageType('danger');
            return;
        }
        setLoading(true);
        setMessage('');
        try {
            const res = await fetch('http://localhost:3001/api/categorias', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    nombre_categoria: cat.name,
                    codigo_categoria: cat.code || null
                })
            });
            const result = await res.json();
            if (result.success) {
                setMessage('Categoría agregada con éxito');
                setMessageType('success');
                loadCategories();
            } else {
                setMessage(result.message || 'Error desconocido al agregar categoría');
                setMessageType('danger');
            }
        } catch (error) {
            console.error("Error agregando categoría en frontend:", error);
            setMessage('Error de comunicación al agregar categoría');
            setMessageType('danger');
        } finally {
            setLoading(false);
        }
    };

    const handleDeleteCategory = async (categoryId) => {
        setLoading(true);
        setMessage('');
        try {
            const res = await fetch(`http://localhost:3001/api/categorias/${categoryId}`, {
                method: 'DELETE'
            });
            const result = await res.json();
            if (result.success) {
                setMessage('Categoría eliminada con éxito');
                setMessageType('success');
                loadCategories();
                loadProducts();
            } else {
                setMessage(result.message || 'Error al eliminar categoría');
                setMessageType('danger');
            }
        } catch (error) {
            console.error("Error al eliminar categoría en frontend:", error);
            setMessage('Error de comunicación al eliminar categoría');
            setMessageType('danger');
        } finally {
            setLoading(false);
        }
    };

    const handleDeleteProduct = async (productId) => {
        if (window.confirm(`¿Estás seguro de que quieres eliminar el producto con ID ${productId}?`)) {
            setLoading(true);
            setMessage('');
            try {
                const res = await fetch(`http://localhost:3001/api/productos/${productId}`, {
                    method: 'DELETE'
                });
                const result = await res.json();
                if (result.success) {
                    setMessage('Producto eliminado con éxito');
                    setMessageType('success');
                    loadProducts();
                } else {
                    setMessage(result.message || 'Error al eliminar producto');
                    setMessageType('danger');
                }
            } catch (err) {
                console.error("Error al eliminar producto en frontend:", err);
                setMessage('Error de comunicación al eliminar producto');
                setMessageType('danger');
            } finally {
                setLoading(false);
            }
        }
    };

    return (
        <div className="max-w-7xl mx-auto py-6 px-4">
            <h1 className="text-center mb-6 text-2xl font-bold text-gray-700">Módulo de Gestión de Inventario</h1>
            <Notification
                message={message}
                type={messageType}
                onClose={() => setMessage('')}
            />

            <div className="rounded-lg shadow mb-6 bg-white">
                <div className="bg-gray-100 border-b border-gray-200 font-semibold px-4 py-2 flex justify-between items-center">
                    <h5 className="mb-0">Agregar Nuevo Producto</h5>
                    <button
                        type="button"
                        id="toggleCategoryButton"
                        className="border border-blue-600 text-blue-600 bg-white hover:bg-blue-50 rounded px-3 py-1 text-sm flex items-center gap-1"
                        onClick={() => setShowCategory(!showCategory)}
                    >
                        <i className="bi bi-plus-lg"></i>
                        <span>Gestionar Categorías</span>
                        <i className={`bi ${showCategory ? 'bi-chevron-up' : 'bi-chevron-down'}`}></i>
                    </button>
                </div>
                <div className="p-4">
                    <CategoryCollapse
                        show={showCategory}
                        categories={categories}
                        onAddCategory={handleAddCategory}
                        onDeleteCategory={handleDeleteCategory}
                        onClose={() => setShowCategory(false)}
                    />
                    <AddProductForm
                        categories={categories}
                        onProductAdded={() => {
                            setMessage('Producto agregado con éxito');
                            setMessageType('success');
                            loadProducts();
                        }}
                    />
                </div>
            </div>

            <ProductsTable
                products={products}
                loading={loading}
                categoryFilter={categoryFilter}
                setCategoryFilter={setCategoryFilter}
                categorias={categories}
                reload={loadProducts}
                onUpdateProduct={handleUpdateProduct}
                onDeleteProduct={handleDeleteProduct}
            />
        </div>
    );
}

export default InventoryPage;
